package cn.courselens;

import android.content.*;import android.database.Cursor;import android.net.Uri;import android.graphics.*;import android.graphics.pdf.PdfRenderer;import android.os.ParcelFileDescriptor;import android.provider.OpenableColumns;import org.json.*;import java.io.*;import java.nio.*;import java.nio.charset.*;import java.util.*;

final class AiAttachment {
 final String name,mime,text;final byte[] image;private JSONObject uploaded;
 private AiAttachment(String name,String mime,String text,byte[] image){this.name=name;this.mime=mime;this.text=text;this.image=image;}
 static AiAttachment screen(byte[] image,long capturedAt){return new AiAttachment("共享画面（捕获于 "+java.time.Instant.ofEpochMilli(capturedAt).atZone(java.time.ZoneId.systemDefault())+"）","image/jpeg",null,image);}
 static List<AiAttachment> read(Context context,Uri uri)throws Exception{
  if(uri==null||!"content".equals(uri.getScheme()))throw new IOException("请选择有效附件");String name="附件";try(Cursor cursor=context.getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0);}if(name==null)name="附件";name=name.replaceAll("[\\p{Cntrl}]"," ");if(name.length()>128)name=name.substring(0,128);
  byte[] data;try(InputStream in=context.getContentResolver().openInputStream(uri)){data=bounded(in,10*1024*1024);}return decode(context,name,data);
 }
 static byte[] bounded(InputStream in,int limit)throws Exception{if(in==null)throw new IOException("附件无法读取");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>limit)throw new IOException("附件过大，请缩小后添加");out.write(buffer,0,n);}return out.toByteArray();}
 static List<AiAttachment> decode(Context context,String name,byte[] data)throws Exception{
  BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,options);if(options.outWidth>0&&options.outHeight>0){if(!Arrays.asList("image/jpeg","image/png","image/webp","image/gif").contains(options.outMimeType)||data.length>8*1024*1024||(long)options.outWidth*options.outHeight>32000000)throw new IOException("图片格式或尺寸不支持，请使用不超过 8 MB、3200 万像素的 JPEG、PNG、GIF 或 WebP");return Collections.singletonList(new AiAttachment(name,options.outMimeType,null,data));}
  if(data.length>4&&data[0]=='%'&&data[1]=='P'&&data[2]=='D'&&data[3]=='F')return pdf(context,name,data);
  String text;if(data.length>4&&data[0]=='P'&&data[1]=='K'){File temp=File.createTempFile("ai-document-",".docx",context.getCacheDir());try{try(FileOutputStream out=new FileOutputStream(temp)){out.write(data);}try(java.util.zip.ZipFile zip=new java.util.zip.ZipFile(temp)){java.util.zip.ZipEntry entry=zip.getEntry("word/document.xml");if(entry==null)throw new IOException("仅支持 DOCX、PDF、UTF-8 文本和图片");byte[] xml;try(InputStream in=zip.getInputStream(entry)){xml=bounded(in,256*1024);}String source=new String(xml,StandardCharsets.UTF_8);if(source.contains("<!DOCTYPE")||source.contains("<!ENTITY"))throw new IOException("文档格式不安全");org.xmlpull.v1.XmlPullParser parser=android.util.Xml.newPullParser();parser.setInput(new StringReader(source));StringBuilder content=new StringBuilder();int event;while((event=parser.next())!=org.xmlpull.v1.XmlPullParser.END_DOCUMENT){if(event==org.xmlpull.v1.XmlPullParser.TEXT)content.append(parser.getText());if(event==org.xmlpull.v1.XmlPullParser.END_TAG&&parser.getName().endsWith("p"))content.append('\n');if(content.length()>64000)throw new IOException("文档文字超过 64000 字，请拆分后添加");}text=content.toString();}}finally{temp.delete();}}
  else{if(data.length>256*1024)throw new IOException("文本文件不能超过 256 KB");try{text=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(data)).toString();}catch(CharacterCodingException e){throw new IOException("文件格式不支持，请使用 DOCX、PDF、UTF-8 文本或图片");}}
  if(text.trim().isEmpty()||text.length()>64000||text.indexOf(0)>=0)throw new IOException("附件内容为空、过长或格式不支持");return Collections.singletonList(new AiAttachment(name,"text/plain",text,null));
 }
 private static List<AiAttachment> pdf(Context context,String name,byte[] data)throws Exception{File temp=File.createTempFile("ai-pages-",".pdf",context.getCacheDir());try{try(FileOutputStream out=new FileOutputStream(temp)){out.write(data);}try(ParcelFileDescriptor descriptor=ParcelFileDescriptor.open(temp,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer pdf=new PdfRenderer(descriptor)){if(pdf.getPageCount()<1||pdf.getPageCount()>4)throw new IOException("PDF 最多支持 4 页，请拆分后添加");List<AiAttachment> result=new ArrayList<>();for(int i=0;i<pdf.getPageCount();i++)try(PdfRenderer.Page page=pdf.openPage(i)){float scale=1280f/Math.max(page.getWidth(),page.getHeight());Bitmap bitmap=Bitmap.createBitmap(Math.max(1,Math.round(page.getWidth()*scale)),Math.max(1,Math.round(page.getHeight()*scale)),Bitmap.Config.ARGB_8888);try{bitmap.eraseColor(Color.WHITE);page.render(bitmap,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);ByteArrayOutputStream jpeg=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.JPEG,85,jpeg);result.add(new AiAttachment(name+" · 第 "+(i+1)+" 页","image/jpeg",null,jpeg.toByteArray()));}finally{bitmap.recycle();}}return result;}}finally{temp.delete();}}
 JSONObject upload(String key,DeepSeekClient.Call call)throws Exception{if(image==null)return new JSONObject().put("kind","text").put("name",name).put("text",text);if(uploaded==null)uploaded=DeepSeekClient.uploadImage(key,name,mime,image,call);return new JSONObject(uploaded.toString()).put("name",name).put("kind","image");}
 JSONObject upload(AiProviders.Config provider,DeepSeekClient.Call call)throws Exception{
  if(image==null)return new JSONObject().put("kind","text").put("name",name).put("text",text);
  if(call.cancelled)throw new IOException("已停止回复");
  if(provider.deepseek)return DeepSeekClient.uploadImage(provider.base,provider.key,name,mime,image,call).put("name",name).put("kind","image").put("origin",provider.base).put("provider",provider.id);
  byte[] bytes=image;String type=mime;
  if(bytes.length>256*1024){BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);options.inSampleSize=1;while(Math.max(options.outWidth,options.outHeight)/options.inSampleSize>1024)options.inSampleSize*=2;options.inJustDecodeBounds=false;Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(bitmap==null)throw new IOException("图片无法读取");try{ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.JPEG,75,out);bytes=out.toByteArray();type="image/jpeg";}finally{bitmap.recycle();}}
  if(bytes.length>512*1024)throw new IOException("图片内容较大，请裁剪后重新添加。");
  return new JSONObject().put("kind","image").put("name",name).put("mime",type).put("data",android.util.Base64.encodeToString(bytes,android.util.Base64.NO_WRAP));
 }
}
